import{_ as d}from"./chunks/theme.CuOqL1SM.js";import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"快速开始","description":"五分钟跑通 CertHub 的第一条证书流水线：配置授权、创建流水线、手动运行一次。","frontmatter":{"title":"快速开始","description":"五分钟跑通 CertHub 的第一条证书流水线：配置授权、创建流水线、手动运行一次。"},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md","lastUpdated":null}'),s={name:"docs/index.md"};function n(l,t,i,h,p,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>CertHub 是<strong>完全免费</strong>的 SSL 证书自动化管理系统：申请、DNS 验证、部署、监控与续期全部编排进一条可视化流水线，不含任何数量限制。</p><p><img src="'+d+`" alt="工作台"></p><h2 id="三步跑通第一条流水线" tabindex="-1">三步跑通第一条流水线 <a class="header-anchor" href="#三步跑通第一条流水线" aria-label="Permalink to &quot;三步跑通第一条流水线&quot;">​</a></h2><h3 id="_1-配置授权" tabindex="-1">1. 配置授权 <a class="header-anchor" href="#_1-配置授权" aria-label="Permalink to &quot;1. 配置授权&quot;">​</a></h3><p>进入 <strong>授权管理 → 新建授权</strong>，选择类型（云厂商 / 主机 / 面板 / 证书签发），把凭据填进去，点「测试」确认能连通。</p><table tabindex="0"><thead><tr><th>你的场景</th><th>该建哪种授权</th></tr></thead><tbody><tr><td>域名托管在阿里云 / 腾讯云 / Cloudflare</td><td>对应的<strong>云厂商</strong>授权（用 DNS-01 验证）</td></tr><tr><td>要部署到自己的服务器</td><td><strong>主机 SSH</strong> 授权</td></tr><tr><td>要部署到宝塔 / 1Panel / 群晖</td><td>对应的<strong>面板</strong>授权</td></tr><tr><td>用 Google Trust Services / FreeSSL 签发</td><td><strong>EAB 凭据</strong>（证书签发分类）</td></tr></tbody></table><p>凭据在数据库里 AES-GCM 加密存储，界面上的密码框默认显示星号，点右侧「小眼睛」可查看明文 —— 这是刻意设计，方便排障时确认到底填了什么。</p><h3 id="_2-创建流水线" tabindex="-1">2. 创建流水线 <a class="header-anchor" href="#_2-创建流水线" aria-label="Permalink to &quot;2. 创建流水线&quot;">​</a></h3><p><strong>证书流水线 → 新建流水线</strong>，两种起步方式：</p><ul><li><strong>从模板创建</strong>：内置 8 套模板（Let&#39;s Encrypt + Nginx / SSH / 阿里云 CDN / 腾讯云 CDN / HTTP 验证 / 火山引擎 + CDN / 仅申请 / 自签测试），套用后补域名与授权即可。</li><li><strong>空白创建</strong>：自己加阶段与任务，适合流程比较特殊的场景。</li></ul><p>一条典型的流水线包含三个阶段：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段 1 申请证书   →  CertApply（选 CA、填域名、选 DNS 授权）</span></span>
<span class="line"><span>阶段 2 部署证书   →  DeployToNginx / DeployToHost / 云 CDN …</span></span>
<span class="line"><span>阶段 3 通知       →  Notify（选通知渠道）</span></span></code></pre></div><h3 id="_3-手动运行一次" tabindex="-1">3. 手动运行一次 <a class="header-anchor" href="#_3-手动运行一次" aria-label="Permalink to &quot;3. 手动运行一次&quot;">​</a></h3><p>点右上角 <strong>运行</strong>（有未保存改动时按钮会变成「保存并运行」）。画布下方的日志坞会<strong>逐行实时</strong>输出执行过程，失败的任务整张卡片标红，并给出中文原因。</p><p>跑通之后：</p><ol><li>打开 <strong>证书库</strong>，确认新证书已入库（域名、签发机构、剩余天数）。</li><li>打开 <strong>定时任务</strong>，设成每天凌晨跑一次 —— 之后到期前会自动续期，不用再管。</li><li>在 <strong>通知渠道</strong> 里配一个机器人或邮件，续期失败时能第一时间收到。</li></ol><div class="tip custom-block"><p class="custom-block-title">首次登录</p><p>默认账号 <code>admin</code> / <code>123456</code>，登录后请立刻在 <strong>账号安全</strong> 里改密码，并建议开启两步验证。</p></div><h2 id="界面地图" tabindex="-1">界面地图 <a class="header-anchor" href="#界面地图" aria-label="Permalink to &quot;界面地图&quot;">​</a></h2><p>侧边栏按「流程」分组，第一次用按这个顺序走一遍即可：</p><table tabindex="0"><thead><tr><th>分组</th><th>页面</th><th>作用</th></tr></thead><tbody><tr><td>概览</td><td>工作台</td><td>流水线、有效证书、运行成功率、站点状态、主机资源</td></tr><tr><td>证书流程</td><td>证书流水线</td><td>编排申请 → 部署 → 通知</td></tr><tr><td>证书流程</td><td>执行历史</td><td>每次运行的结果、耗时、任务数与完整日志</td></tr><tr><td>证书流程</td><td>证书库</td><td>已签发证书、剩余天数、格式导出</td></tr><tr><td>接入资源</td><td>授权管理</td><td>DNS、主机、面板、云厂商、EAB 凭据</td></tr><tr><td>接入资源</td><td>DNS 记录</td><td>托管在平台里的解析记录（手动申请时用）</td></tr><tr><td>接入资源</td><td>站点监控</td><td>定时巡检站点证书，到期前告警</td></tr><tr><td>接入资源</td><td>通知渠道</td><td>邮件、Webhook、钉钉 / 飞书 / 企微机器人等</td></tr><tr><td>系统</td><td>系统设置</td><td>站点信息、网络代理、安全策略、到期提醒</td></tr><tr><td>系统</td><td>用户管理</td><td>账号、用户组与功能权限</td></tr><tr><td>系统</td><td>审计日志</td><td>谁在什么时候改了什么</td></tr><tr><td>系统</td><td>开放接口</td><td>给脚本 / CI 用的 API 密钥</td></tr></tbody></table><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li>还没装？看 <a href="./install.html">安装部署</a></li><li>搞不清「阶段 / 任务 / 连线」？看 <a href="./concept.html">核心概念</a></li><li>授权字段不知道填什么？看 <a href="./access.html">授权管理</a></li><li>签发失败、DNS 一直不生效？看 <a href="./troubleshoot.html">故障排查</a></li></ul>`,23)])])}const _=a(s,[["render",n]]);export{b as __pageData,_ as default};
